            ),
            'references': [
                'docs/math/C_inhomogeneous_definition.md',
                'docs/math/B0n_schema_v5.md',
                'Issue I06-1',
            ],
        },
    }


# ──────────────────────────────────────────────────────────────────
# Main
# ──────────────────────────────────────────────────────────────────

def main() -> None:
